static inline int aether_cjk_find(unsigned cp)
{
    int lo = 0, hi = (int)AETHER_CJK_COUNT - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        unsigned v = aether_cjk_cp[mid];
        if (v == cp) return mid;
        if (v < cp) lo = mid + 1; else hi = mid - 1;
    }
    return -1;
}

